package com.bank.cache.service;

import com.bank.cache.dto.CacheResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

@Service
@Slf4j
public class AccountCacheService {

    // Simulated cache
    private final Map<String, String> cache = Map.of(
        "SAV2001", "Rajesh Kumar (cached)",
        "CUR3001", "Priya Sharma (cached)"
    );

    private final AtomicInteger dbCallCounter = new AtomicInteger(0);

    // Simulated EXPENSIVE DB call
    private String fetchFromDatabase(String accountId) {
        dbCallCounter.incrementAndGet();
        log.info(" DB QUERY executed for {} — EXPENSIVE!", accountId);
        // Simulate DB latency
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return accountId + " (from DB)";
    }

    // ═══ orElse — DB call ALWAYS executed (even on cache hit!) ═══
    public CacheResult lookupWithOrElse(String accountId) {
        dbCallCounter.set(0);

        String fromCache = cache.get(accountId);  // might be null

        // (Avoid) orElse: fetchFromDatabase ALWAYS runs, even when fromCache is non-null!
        String result = Optional.ofNullable(fromCache)
            .orElse(fetchFromDatabase(accountId));

        return new CacheResult("orElse (EAGER)", accountId,
            fromCache != null ? "CACHE (but DB was still called!)" : "DB",
            dbCallCounter.get(),
            fromCache != null
                ? "(Caution) Cache HIT but fetchFromDatabase() still executed! Wasted DB call."
                : "Cache MISS — DB call was needed.");
    }

    // ═══ orElseGet — DB call ONLY on cache miss ═══
    public CacheResult lookupWithOrElseGet(String accountId) {
        dbCallCounter.set(0);

        String fromCache = cache.get(accountId);

        // (Recommended) orElseGet: fetchFromDatabase runs ONLY when Optional is empty
        String result = Optional.ofNullable(fromCache)
            .orElseGet(() -> fetchFromDatabase(accountId));

        return new CacheResult("orElseGet (LAZY)", accountId,
            fromCache != null ? "CACHE (DB NOT called!)" : "DB",
            dbCallCounter.get(),
            fromCache != null
                ? "(Recommended) Cache HIT — fetchFromDatabase() was NOT called. Zero waste."
                : "Cache MISS — DB call was needed (Supplier invoked).");
    }

    // ═══ Comparison: 10 lookups, 8 cache hits ═══
    public Map<String, Object> benchmark() {
        List<String> ids = List.of("SAV2001", "CUR3001", "SAV2001", "UNKNOWN1",
            "SAV2001", "CUR3001", "UNKNOWN2", "SAV2001", "CUR3001", "SAV2001");

        // orElse: count DB calls
        AtomicInteger orElseCalls = new AtomicInteger(0);
        ids.forEach(id -> {
            String cached = cache.get(id);
            Optional.ofNullable(cached).orElse(simulateDbCall(id, orElseCalls));
        });

        // orElseGet: count DB calls
        AtomicInteger orElseGetCalls = new AtomicInteger(0);
        ids.forEach(id -> {
            String cached = cache.get(id);
            Optional.ofNullable(cached).orElseGet(() -> simulateDbCall(id, orElseGetCalls));
        });

        return Map.of(
            "totalLookups", ids.size(),
            "cacheHits", ids.stream().filter(cache::containsKey).count(),
            "cacheMisses", ids.stream().filter(id -> !cache.containsKey(id)).count(),
            "orElse_dbCalls", orElseCalls.get(),
            "orElseGet_dbCalls", orElseGetCalls.get(),
            "verdict", "orElse: " + orElseCalls.get() + " DB calls | orElseGet: "
                + orElseGetCalls.get() + " DB calls — orElseGet saved "
                + (orElseCalls.get() - orElseGetCalls.get()) + " unnecessary queries!"
        );
    }

    private String simulateDbCall(String id, AtomicInteger counter) {
        counter.incrementAndGet();
        return id + " (DB)";
    }
}
