package com.bank.cache.controller;

import com.bank.cache.dto.CacheResult;
import com.bank.cache.service.AccountCacheService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/cache")
@RequiredArgsConstructor
public class CacheController {

    private final AccountCacheService cacheService;

    @GetMapping("/orElse/{accountId}")
    public CacheResult orElse(@PathVariable String accountId) {
        return cacheService.lookupWithOrElse(accountId);
    }

    @GetMapping("/orElseGet/{accountId}")
    public CacheResult orElseGet(@PathVariable String accountId) {
        return cacheService.lookupWithOrElseGet(accountId);
    }

    @GetMapping("/benchmark")
    public Map<String, Object> benchmark() { return cacheService.benchmark(); }
}
