package com.bank.cache.service;

import org.junit.jupiter.api.Test;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class OrElseVsOrElseGetTest {

    @Test
    void orElseAlwaysEvaluatesDefault() {
        AtomicInteger counter = new AtomicInteger(0);

        // Present Optional — orElse STILL evaluates the default!
        String result = Optional.of("CACHED")
            .orElse(expensiveDefault(counter));

        assertThat(result).isEqualTo("CACHED");
        assertThat(counter.get()).isEqualTo(1);  // default WAS evaluated (wasted!)
    }

    @Test
    void orElseGetOnlyEvaluatesWhenEmpty() {
        AtomicInteger counter = new AtomicInteger(0);

        // Present Optional — orElseGet does NOT evaluate the default
        String result = Optional.of("CACHED")
            .orElseGet(() -> expensiveDefault(counter));

        assertThat(result).isEqualTo("CACHED");
        assertThat(counter.get()).isZero();  // default was NOT evaluated (saved!)
    }

    @Test
    void bothEvaluateWhenEmpty() {
        AtomicInteger counter1 = new AtomicInteger(0);
        AtomicInteger counter2 = new AtomicInteger(0);

        String r1 = Optional.<String>empty().orElse(expensiveDefault(counter1));
        String r2 = Optional.<String>empty().orElseGet(() -> expensiveDefault(counter2));

        assertThat(counter1.get()).isEqualTo(1);  // evaluated (needed)
        assertThat(counter2.get()).isEqualTo(1);  // evaluated (needed)
        assertThat(r1).isEqualTo(r2);  // same result
    }

    @Test
    void benchmarkShowsDifference() {
        AtomicInteger orElseCalls = new AtomicInteger(0);
        AtomicInteger orElseGetCalls = new AtomicInteger(0);

        // 100 lookups, 80% cache hits
        for (int i = 0; i < 100; i++) {
            Optional<String> opt = i % 5 == 0 ? Optional.empty() : Optional.of("cached");

            opt.orElse(expensiveDefault(orElseCalls));
            opt.orElseGet(() -> expensiveDefault(orElseGetCalls));
        }

        assertThat(orElseCalls.get()).isEqualTo(100);   // ALL 100 evaluated!
        assertThat(orElseGetCalls.get()).isEqualTo(20);  // only 20 misses evaluated!
    }

    private String expensiveDefault(AtomicInteger counter) {
        counter.incrementAndGet();
        return "DEFAULT";
    }
}
